class ScheduledWizardPage extends StatefulWidget{const ScheduledWizardPage({super.key,required this.controller,this.campaign});final AppController controller;final ApiScheduledCampaign? campaign;@override State<ScheduledWizardPage> createState()=>_ScheduledWizardPageState();}
class _ScheduledWizardPageState extends State<ScheduledWizardPage>{
  late final TextEditingController _name,_hours;late String _selectionMode,_targetMode;late Set<int> _groupIds;late bool _enabled;ApiMessageContent _initial=const ApiMessageContent(components:[]);int _step=0;bool _saving=false;bool get editing=>widget.campaign!=null;
  @override void initState(){super.initState();final c=widget.campaign;_name=TextEditingController(text:c?.name??'');_hours=TextEditingController(text:c==null?'12':_hoursText(c.intervalSeconds));_selectionMode=c?.selectionMode??'shuffle';_targetMode=c?.targetMode??'all';_groupIds={...?c?.groupIds};_enabled=c?.enabled??false;}
  @override void dispose(){_name.dispose();_hours.dispose();super.dispose();}
