class ScheduledDetailsPage extends StatefulWidget{const ScheduledDetailsPage({super.key,required this.controller,required this.campaignId});final AppController controller;final int campaignId;@override State<ScheduledDetailsPage> createState()=>_ScheduledDetailsPageState();}
