class _ContentDraftPage extends StatefulWidget{const _ContentDraftPage({required this.controller});final AppController controller;@override State<_ContentDraftPage> createState()=>_ContentDraftPageState();}
class _ContentDraftPageState extends State<_ContentDraftPage>{ApiMessageContent _content=const ApiMessageContent(components:[]);@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('إضافة رسالة للجدول')),body:ListView(padding:const EdgeInsets.all(16),children:[ContentComposer(controller:widget.controller,value:_content,onChanged:(v)=>setState(()=>_content=v)),const SizedBox(height:20),FilledButton.icon(onPressed:_content.isEmpty?null:()=>Navigator.pop(context,_content),icon:const Icon(Icons.check_rounded),label:const Text('اعتماد المحتوى'))]));}
String _hoursText(int s){final h=s/3600;return h==h.roundToDouble()?h.toInt().toString():h.toStringAsFixed(2);}String _intervalLabel(int s){if(s<=0)return'—';if(s%86400==0)return'كل ${s~/86400} يوم';if(s%3600==0)return'كل ${s~/3600} ساعة';if(s%60==0)return'كل ${s~/60} دقيقة';return'كل $s ثانية';}String _selectionLabel(String m)=>switch(m){'shuffle'=>'عشوائي بدون تكرار','random'=>'عشوائي بالكامل','ordered'=>'بالترتيب',_=>m};String _date(int? ms){if(ms==null||ms<=0)return'—';final d=DateTime.fromMillisecondsSinceEpoch(ms).toLocal();String t(int v)=>v.toString().padLeft(2,'0');return'${d.year}-${t(d.month)}-${t(d.day)} ${t(d.hour)}:${t(d.minute)}';}
